svg.script:
(function(){
var SVG='http://www.w3.org/2000/svg';
var root=document.getElementById('buildRoot'); if(!root) return;
function ns(t,a,txt){var e=document.createElementNS(SVG,t);if(a)for(var k in a)e.setAttribute(k,a[k]);if(txt!=null)e.textContent=txt;root.appendChild(e);return e;}
var phi=53.2*Math.PI/180;
var cx=320,cy=300,Rmax=185,Rmin=92,Router=210,M=24,i;
var lo=1e9,hi=-1e9;
for(i=0;i<365;i++){
  var decl=23.44*Math.PI/180*Math.cos(2*Math.PI*(i-172)/365.25);
  var cH=-Math.tan(phi)*Math.tan(decl); if(cH>1)cH=1; if(cH<-1)cH=-1;
  var H=Math.acos(cH)*180/Math.PI; var sr=12-H/15;
  var B=2*Math.PI*(i-81)/365.25; var e=9.87*Math.sin(2*B)-7.53*Math.cos(B)-1.5*Math.sin(B);
  var c=sr-e/60; if(c<lo)lo=c; if(c>hi)hi=c;
}
var pts=[];
for(i=0;i<M;i++){
  var ang=i/M*2*Math.PI;
  var Nf=172+ang/(2*Math.PI)*365.25;
  var decl2=23.44*Math.PI/180*Math.cos(2*Math.PI*(Nf-172)/365.25);
  var cH2=-Math.tan(phi)*Math.tan(decl2); if(cH2>1)cH2=1; if(cH2<-1)cH2=-1;
  var H2=Math.acos(cH2)*180/Math.PI; var sr2=12-H2/15;
  var B2=2*Math.PI*(Nf-81)/365.25; var e2=9.87*Math.sin(2*B2)-7.53*Math.cos(B2)-1.5*Math.sin(B2);
  var c2=sr2-e2/60;
  var r=Rmin+(Rmax-Rmin)*(hi-c2)/(hi-lo);
  pts.push({x:cx+r*Math.sin(ang),y:cy-r*Math.cos(ang)});
}
function crClosed(p){var n=p.length,d='M'+p[0].x.toFixed(2)+' '+p[0].y.toFixed(2),j;
  for(j=0;j<n;j++){var a=p[(j-1+n)%n],b=p[j],c=p[(j+1)%n],e=p[(j+2)%n];
    var c1x=b.x+(c.x-a.x)/6,c1y=b.y+(c.y-a.y)/6,c2x=c.x-(e.x-b.x)/6,c2y=c.y-(e.y-b.y)/6;
    d+='C'+c1x.toFixed(2)+' '+c1y.toFixed(2)+' '+c2x.toFixed(2)+' '+c2y.toFixed(2)+' '+c.x.toFixed(2)+' '+c.y.toFixed(2);}
  return d+'Z';}
ns('circle',{cx:cx,cy:cy,r:Rmax,'class':'base'});
ns('circle',{cx:cx,cy:cy,r:2.5,'class':'lab'});
var cards=[
 {i:0,  t:'21 Jun', x:cx,           y:cy-Router-16, a:'middle'},
 {i:3,  t:'6 Aug',  x:cx+161,       y:cy-155,       a:'start'},
 {i:6,  t:'20 Sep', x:cx+Router+12, y:cy+5,         a:'start'},
 {i:9,  t:'5 Nov',  x:cx+161,       y:cy+165,       a:'start'},
 {i:12, t:'21 Dec', x:cx,           y:cy+Router+22, a:'middle'},
 {i:15, t:'4 Feb',  x:cx-161,       y:cy+165,       a:'end'},
 {i:18, t:'22 Mar', x:cx-Router-12, y:cy+5,         a:'end'},
 {i:21, t:'6 May',  x:cx-161,       y:cy-155,       a:'end'}
];
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var spokes=[],dots=[],cardEls=[],ci;
for(i=0;i<M;i++){
  var ang2=i/M*2*Math.PI;
  var s=ns('line',{x1:cx,y1:cy,x2:cx+Router*Math.sin(ang2),y2:cy-Router*Math.cos(ang2),'class':'spoke','stroke-width':1});
  s.style.transition='opacity .45s ease'; s.style.opacity=reduce?1:0; spokes.push(s);
}
for(ci=0;ci<cards.length;ci++){
  var L=ns('text',{x:cards[ci].x,y:cards[ci].y,'font-size':13,'class':'lab','text-anchor':cards[ci].a},cards[ci].t);
  L.style.transition='opacity .45s ease'; L.style.opacity=reduce?1:0; cardEls.push({el:L,i:cards[ci].i});
}
var spline=ns('path',{d:crClosed(pts),'class':'cam','stroke-width':2.6});
for(i=0;i<M;i++){var dd=ns('circle',{cx:pts[i].x,cy:pts[i].y,r:4,'class':'dot'}); dd.style.transition='opacity .45s ease'; dd.style.opacity=reduce?1:0; dots.push(dd);}
var len=spline.getTotalLength();
spline.style.strokeDasharray=len; spline.style.strokeDashoffset=reduce?0:len;
if(reduce) return;
var loop;
function run(){
  spokes.forEach(function(s){s.style.opacity=0;});
  dots.forEach(function(d){d.style.opacity=0;});
  cardEls.forEach(function(c){c.el.style.opacity=0;});
  spline.style.transition='none'; spline.style.strokeDashoffset=len;
  void root.getBBox();
  spokes.forEach(function(s,k){setTimeout(function(){s.style.opacity=1;},200+k*55);});
  cardEls.forEach(function(c){setTimeout(function(){c.el.style.opacity=1;},200+c.i*55);});
  var dStart=200+M*55+200;
  dots.forEach(function(d,k){setTimeout(function(){d.style.opacity=1;},dStart+k*55);});
  var sStart=dStart+M*55+250;
  setTimeout(function(){spline.style.transition='stroke-dashoffset 1.5s ease'; spline.style.strokeDashoffset=0;},sStart);
  loop=setTimeout(run, sStart+1500+2600);
}
run();
})();
